    filterSituation: function () {
        var values = [];
        this.getSituationItemsMenu().forEach(
            function (item) {
                if (item.checked)
                    values.push(item.value);
            }
        );
        this.setFilterProperty('ativo__in', values, 4);
    },


    _setMain: function (pk) {
        var rest = this.factoryRestful();
        var mask = new Ext.LoadMask(this.getEl(), { msg: 'criando Exercício...' });

        mask.show();
        rest.setMain(
            pk,
            true,
            {
                scope: this,
                fn: function () {
                    this.getStore().reload();
                }
            },
            {
                fn: function (message) {
                    Ext.Msg.show({
                        title: 'Adicionando',
                        msg: message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
                }
            },
            {
                fn: function () {
                    mask.hide();
                }
            }
        );
    },

    getSetMainAction: function (cfg) {
        if (!this._setMainAction) {
            this._setMainAction = Ext._create('Ext.Button', {
                text: 'Marcar como Principal...',
                iconCls: 'icon-core icon-core-reports',
                scope: this,
                handler: function () {
                    if (this.getSelectionModel().getSelected())
                        this._setMain(this.getSelectionModel().getSelected().id);
                    else
                        Ext.Msg.show({
                            title: 'Maracando como Principal',
                            msg: 'Primeiro selecione uma lotação.',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        });

                }
            });
        }
        return this._setMainAction;
    },

